// === Tab: mySketch.js ===
p5.disableFriendlyErrors = true

function linear(t) {
  return t
}

function easeInSine(t) {
  return 1 - Math.cos(t * Math.PI * 0.5);
}

function easeOutSine(t) {
  return Math.sin(t * Math.PI * 0.5);
}

function easeInOutSine(t) {
  return -0.5 * (Math.cos(t * Math.PI) - 1);
}

function easeInQuad(t) {
  return t ** 2;
}

function easeOutQuad(t) {
  return 1 - Math.abs((t - 1) ** 2);
}

function easeInOutQuad(t) {
  return t < 0.5
    ? (t * 2) ** 2 * 0.5
    : (1 - Math.abs(((t * 2) - 2) ** 2)) * 0.5 + 0.5
}

function easeInCubic(t) {
  return t ** 3;
}

function easeOutCubic(t) {
  return 1 - Math.abs((t - 1) ** 3);
}

function easeInOutCubic(t) {
  return t < 0.5
    ? (t * 2) ** 3 * 0.5
    : (1 - Math.abs(((t * 2) - 2) ** 3)) * 0.5 + 0.5;
}

function easeInQuart(t) {
  return t ** 4;
}

function easeOutQuart(t) {
  return 1 - Math.abs((t - 1) ** 4);
}

function easeInOutQuart(t) {
  return t < 0.5
    ? (t * 2) ** 4 * 0.5
    : (1 - Math.abs(((t * 2) - 2) ** 3)) * 0.5 + 0.5;
}

function easeInQuint(t) {
  return t ** 5;
}

function easeOutQuint(t) {
  return 1 - Math.abs((t - 1) ** 5);
}

function easeInOutQuint(t) {
  return t < 0.5
    ? (t * 2) ** 5 * 0.5
    : (1 - Math.abs(((t * 2) - 2) ** 3)) * 0.5 + 0.5;
}

function easeInExpo(t) {
  return t === 0 ? 0 : 2 ** (10 * (t - 1));
}

function easeOutExpo(t) {
  return t === 1 ? 1 : 1 - 2 ** (-10 * t);
}

function easeInOutExpo(t) {
  return t === 0 || t === 1
    ? t
    : t < 0.5
      ? 0.5 * (2 ** (10 * 2 * (t - 0.5)))
      : 0.5 * (2 - Math.abs(2 ** (-10 * 2 * (t - 0.5))));
}

function easeInCirc(t) {
  return Math.abs(Math.sqrt(1 - (t ** 2)) - 1);
}

function easeOutCirc(t) {
  return Math.sqrt(1 - ((t - 1) ** 2));
}

function easeInOutCirc(t) {
  return t < 0.5
    ? -0.5 * (Math.sqrt(1 - (2 * t) ** 2) - 1)
    : 0.5 * (Math.sqrt(1 - (2 * t - 2) ** 2) + 1);
}

function easeInElastic(t, magnitude = 0.7) {
  if (t === 0 || t === 1) {
    return t;
  }

  const scaledTime = t - 1;

  const p = 1 - magnitude;
  const s = p / (2 * Math.PI) * Math.asin(1);

  return -1 * 2 ** (10 * scaledTime )
    * Math.sin((scaledTime - s)
    * (2 * Math.PI) / p);
}

function easeOutElastic(t, magnitude = 0.7) {
  var p = 1 - magnitude;
  var scaledTime = t * 2;

  if ( t === 0 || t === 1 ) {
    return t;
  }

  var s = p / (2 * Math.PI) * Math.asin(1);
  return 2 ** (-10 * scaledTime)
    * Math.sin((scaledTime - s)
    * (2 * Math.PI) / p) + 1;
}

function easeInOutElastic(t, magnitude = 0.65) {
  var p = 1 - magnitude;

  if (t === 0 || t === 1) {
    return t;
  }

  var scaledTime = t * 2;
  const scaledTime1 = scaledTime - 1;

  var s = p / (2 * Math.PI) * Math.asin(1);

  if (scaledTime < 1) {
    return -0.5 * (
        Math.pow( 2, 10 * scaledTime1 ) *
        Math.sin( ( scaledTime1 - s ) * ( 2 * Math.PI ) / p )
    );
  }

  return (Math.pow(2, -10 * scaledTime1)
    * Math.sin((scaledTime1 - s) * (2 * Math.PI) / p) * 0.5) + 1;
}

const fns = {
  linear,
  easeInSine, easeOutSine, easeInOutSine,
  easeInQuad, easeOutQuad, easeInOutQuad,
  easeInCubic, easeOutCubic, easeInOutCubic,
  easeInQuart, easeOutQuart, easeInOutQuart,
  easeInQuint, easeOutQuint, easeInOutQuint,
  easeInExpo, easeOutExpo, easeInOutExpo,
  easeInCirc, easeOutCirc, easeInOutCirc,
  easeInElastic, easeOutElastic, easeInOutElastic,
};
const elements = {};

function setup() {
  createCanvas(1, 1).hide();
  const table = createElement('table')
    .style('font-family', 'sans-serif')
    .style('max-width', '1200px')
    .style('margin-left', 'auto')
    .style('margin-right', 'auto');
  for (const key in fns) {

		const preview = createGraphics(50, 50)
		preview.background(255)
		preview.noFill()
		preview.stroke(0)
		preview.beginShape()
		for (let i = 0; i <= 40; i++) {
			const t = map(i, 0, 40, 0, 1)
			preview.vertex(
				lerp(10, preview.width-10, t),
				lerp(preview.height-10, 10, fns[key](t))
			)
		}
		preview.endShape()

    const r = createElement('tr')
      .parent(table);
    const name = createElement('th')
      .html(key)
      .style('padding', '20px 10px')
      .style('vertical-align', 'top')
      .style('text-align', 'left')
      .parent(r);

		const previewContainer = createElement('td')
			.style('width', '100px')
			.parent(r)
		preview.parent(previewContainer)
			.show()

    const code = createElement('td')
      .html(document.createTextNode(fns[key].toString()).textContent)
      .style('font-family', 'monospace')
      .style('white-space', 'pre-wrap')
      .style('padding', '20px 10px')
      .parent(r);
    const display = createElement('td')
      .style('width', '220px')
      .style('padding', '20px 10px')
      .parent(r);
    const element = createElement('div')
      .style('width', '20px')
      .style('height', '20px')
      .style('border-radius', '50%')
      .style('background', 'red')
      .parent(display);

    elements[key] = element
  }
}

function draw() {
  const period = 2000;
  const progress = map((millis() % period), 500, 1500, 0, 1, true);
  for (const key in elements) {
    const easedProgress = fns[key](progress);
    elements[key].style('transform', `translate(${(easedProgress * 200).toFixed(1)}px, 0)`);
  }
}
